//! Training-set utilities for RFS.
//!
//! The training tree is organized as:
//!
//! ```text
//! training/
//!   <category>/
//!     rfs_training.jsonl
//!     snippets/
//!       valid/*.rfs
//!       invalid/*.rfs
//! ```
//!
//! `all_rfs_training.jsonl` at the project root is generated by aggregating all
//! category JSONL files.

use serde_json::Value;
use std::collections::HashSet;
use std::fs;
use std::io::Write;
use std::path::{Path, PathBuf};

#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct SnippetCounts {
    pub valid: usize,
    pub invalid: usize,
}

impl SnippetCounts {
    pub fn total(self) -> usize {
        self.valid + self.invalid
    }
}

pub fn training_root(project_root: &Path) -> PathBuf {
    project_root.join("training")
}

pub fn category_dirs(project_root: &Path) -> std::io::Result<Vec<PathBuf>> {
    let root = training_root(project_root);
    if !root.exists() {
        return Ok(Vec::new());
    }
    let mut dirs = fs::read_dir(root)?
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| path.is_dir())
        .collect::<Vec<_>>();
    dirs.sort();
    Ok(dirs)
}

pub fn category_jsonl_path(category: &Path) -> PathBuf {
    category.join("rfs_training.jsonl")
}

pub fn read_jsonl_lines(path: &Path) -> std::io::Result<Vec<String>> {
    let text = fs::read_to_string(path)?;
    Ok(text
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| line.to_string())
        .collect())
}

pub fn validate_training_line(line: &str) -> Result<(), String> {
    let value: Value = serde_json::from_str(line).map_err(|e| format!("invalid JSONL: {e}"))?;

    let messages = value
        .get("messages")
        .and_then(Value::as_array)
        .ok_or_else(|| "missing `messages` array".to_string())?;

    if messages.len() != 2 {
        return Err(format!("expected 2 messages, found {}", messages.len()));
    }

    let user = &messages[0];
    let assistant = &messages[1];

    if user.get("role").and_then(Value::as_str) != Some("user") {
        return Err("first message role must be `user`".to_string());
    }
    if assistant.get("role").and_then(Value::as_str) != Some("assistant") {
        return Err("second message role must be `assistant`".to_string());
    }

    let user_content = user
        .get("content")
        .and_then(Value::as_str)
        .ok_or_else(|| "missing user content".to_string())?;
    let assistant_content = assistant
        .get("content")
        .and_then(Value::as_str)
        .ok_or_else(|| "missing assistant content".to_string())?;

    if user_content.trim().is_empty() {
        return Err("empty user content".to_string());
    }
    if !assistant_content.starts_with("< think>") || !assistant_content.contains("< /think>") {
        return Err(
            "assistant content must use `< think> ... < /think>` chain-of-thought format"
                .to_string(),
        );
    }

    Ok(())
}

pub fn aggregate_training_sets(project_root: &Path, out: &Path) -> Result<usize, String> {
    let categories = category_dirs(project_root).map_err(|e| e.to_string())?;
    if categories.is_empty() {
        return Err("no training categories found under training/".to_string());
    }

    if let Some(parent) = out.parent() {
        fs::create_dir_all(parent)
            .map_err(|e| format!("failed to create {}: {e}", parent.display()))?;
    }

    let mut file =
        fs::File::create(out).map_err(|e| format!("failed to create {}: {e}", out.display()))?;
    let mut total = 0;

    for category in &categories {
        let path = category_jsonl_path(category);
        if !path.exists() {
            continue;
        }
        for line in read_jsonl_lines(&path).map_err(|e| format!("{}: {e}", path.display()))? {
            validate_training_line(&line)?;
            file.write_all(line.as_bytes())
                .and_then(|_| file.write_all(b"\n"))
                .map_err(|e| format!("failed to write {}: {e}", out.display()))?;
            total += 1;
        }
    }

    Ok(total)
}

pub fn extract_rfs_snippets(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;

    while let Some(start) = rest.find("```rfs") {
        let after_marker = &rest[start + "```rfs".len()..];
        let after_marker = if let Some(stripped) = after_marker.strip_prefix("\r\n") {
            stripped
        } else if let Some(stripped) = after_marker.strip_prefix('\n') {
            stripped
        } else {
            after_marker
        };

        let Some(end) = after_marker.find("```") else {
            break;
        };

        let snippet = after_marker[..end].trim();
        if !snippet.is_empty() {
            out.push(snippet.to_string());
        }

        rest = &after_marker[end + "```".len()..];
    }

    out
}

pub fn extract_category_snippets(category: &Path) -> Result<SnippetCounts, String> {
    let jsonl_path = category_jsonl_path(category);
    if !jsonl_path.exists() {
        return Ok(SnippetCounts::default());
    }

    let mut seen = HashSet::new();
    let mut valid = Vec::new();
    let mut invalid = Vec::new();

    for line in
        read_jsonl_lines(&jsonl_path).map_err(|e| format!("{}: {e}", jsonl_path.display()))?
    {
        let value: Value = serde_json::from_str(&line)
            .map_err(|e| format!("{} invalid JSONL: {e}", jsonl_path.display()))?;

        let messages = value
            .get("messages")
            .and_then(Value::as_array)
            .ok_or_else(|| "missing messages".to_string())?;

        for message in messages {
            let Some(content) = message.get("content").and_then(Value::as_str) else {
                continue;
            };
            for snippet in extract_rfs_snippets(content) {
                if seen.insert(snippet.clone()) {
                    match crate::parse_source(&snippet) {
                        Ok(ir) => {
                            if crate::validator::validate_ir(&ir).is_ok() {
                                valid.push(snippet);
                            } else {
                                invalid.push(snippet);
                            }
                        }
                        Err(_) => invalid.push(snippet),
                    }
                }
            }
        }
    }

    valid.sort();
    invalid.sort();

    let snippets_dir = category.join("snippets");
    if snippets_dir.exists() {
        fs::remove_dir_all(&snippets_dir)
            .map_err(|e| format!("failed to remove {}: {e}", snippets_dir.display()))?;
    }

    let valid_dir = snippets_dir.join("valid");
    let invalid_dir = snippets_dir.join("invalid");
    fs::create_dir_all(&valid_dir)
        .map_err(|e| format!("failed to create {}: {e}", valid_dir.display()))?;
    fs::create_dir_all(&invalid_dir)
        .map_err(|e| format!("failed to create {}: {e}", invalid_dir.display()))?;

    for (idx, snippet) in valid.iter().enumerate() {
        let path = valid_dir.join(format!("snippet_{:04}.rfs", idx + 1));
        fs::write(&path, snippet)
            .map_err(|e| format!("failed to write {}: {e}", path.display()))?;
    }

    for (idx, snippet) in invalid.iter().enumerate() {
        let path = invalid_dir.join(format!("snippet_{:04}.rfs", idx + 1));
        fs::write(&path, snippet)
            .map_err(|e| format!("failed to write {}: {e}", path.display()))?;
    }

    Ok(SnippetCounts {
        valid: valid.len(),
        invalid: invalid.len(),
    })
}

pub fn extract_all_snippets(project_root: &Path) -> Result<Vec<(PathBuf, SnippetCounts)>, String> {
    let mut out = Vec::new();
    for category in category_dirs(project_root).map_err(|e| e.to_string())? {
        let counts = extract_category_snippets(&category)?;
        out.push((category, counts));
    }
    Ok(out)
}
